 if(!/\.html?$/i.test(file.name))return rej(t('Only .html template files are accepted.'));if(file.size>2*1024*1024)return rej(t('The template is larger than 2 MB.'));
 const html=await file.text();if(!/\{\{\s*\w+\s*\}\}/.test(html))return rej(t('The template has no {{placeholders}}.'));if(/<script|\son\w+\s*=/i.test(html))return rej(t('Scripts and event handlers are not allowed in templates.'));
 const unk=unknownPh(html);const v={v:F.vers.length+1,at:TODAY,by:S.uid,html,size:file.size};
 modal(`<h3>${ic('eye')} ${esc(F.nm)} · ${t('New version')} v${v.v}</h3><div class="cb">${unk.length?`<div class="banner wait">${ic('alert')}<span>${t('Unknown placeholders (they print as empty): {p}',{p:unk.map(esc).join(', ')})}</span></div>`:`<div class="banner open">${ic('check')}<span>${t('All placeholders are known.')}</span></div>`}<iframe title="${t('Preview')}" sandbox srcdoc="${esc(fillTpl(html))}" style="width:100%;height:300px;border:1px solid var(--line);border-radius:8px;background:#fff"></iframe>${rsnFld()}</div><div class="ft"><button class="btn" data-act="mclose">${t('Cancel')}</button><button class="btn pri" id="rok2">${t('Publish (needs step-up)')}</button></div>`,{wide:true});
