 <div class="sect thread"><h4>${ic('msg')} ${t('Comments')} (${r.wf.notes.length})</h4>${r.wf.notes.map(n=>`<div class="m">${av(U2[n.by])}<div class="bub ${n.kind==='return'?'ret':''}"><b>${esc((U2[n.by]||{name:n.by}).name)}</b> <small class="mono">${n.at}</small>${n.kind==='return'?` <span class="pill p-late">${t('Returned')}</span>`:''}<br>${esc(n.text)}</div></div>`).join('')||`<div class="hint">${t('No comments yet. A rejection must carry a note; it appears here.')}</div>`}
 <div class="row" style="align-items:flex-start"><textarea class="inp" id="rgcmt" rows="2" style="flex:1" placeholder="${t('Write a comment')}" aria-label="${t('Write a comment')}"></textarea><button class="btn" data-act="rgcomment">${t('Post')}</button></div></div>
