function rgMissing(k,r){return RG[k].f.filter(fd=>fd[3]&&!String(r[fd[0]]==null?'':r[fd[0]]).trim()).map(fd=>t(fd[1]))}
function rgAdvance(k,r,u,done){const lv=rgLv(k),idx=RG[k].idx;let n=lv.indexOf(done)+1;r.wf.skipped=r.wf.skipped||[];
 while(n<lv.length){const L=lv[n],cell=MX[idx][L];if(cell.rule!=='all'&&rgMine(k,L)){r.wf.skipped.push(L);r.wf.hist.push({a:'Skipped '+L,at:TODAY,by:u.id,note:'Same person holds consecutive levels'});audit('Level skipped',rgId(k,r),`${lvName(L)} skipped automatically: ${u.name} holds two consecutive levels`,L,'skipped');n++;continue}r.wf.state=L;return}
 r.wf.state='done'}
