document.addEventListener('keydown',e=>{if(e.key!=='n'||e.ctrlKey||e.metaKey||e.altKey||!me())return;const tg=e.target;if(/^(INPUT|TEXTAREA|SELECT)$/.test(tg.tagName)||tg.isContentEditable||$('#modal')||$('#pal'))return;const r=parseHash();
 if(r.name==='register'&&RG[r.args[0]]&&RG[r.args[0]].newOK){e.preventDefault();ACT.rgnew({dataset:{a:r.args[0]}})}else if(r.name==='settings'&&S.f.set&&S.f.set.tab==='calendar'){e.preventDefault();ACT.calnew({dataset:{}})}else if(r.name==='settings'&&S.f.set&&S.f.set.tab==='staff'&&SF().tab==='list'){e.preventDefault();ACT.stedit({dataset:{}})}});
