 /* absence */
 absadd:()=>{const f=AF(),u=me(),ld=isLead(u),o={uid:ld?$('#ab-uid').value:u.id,kind:ld?$('#ab-kind').value:'annual',from:$('#ab-from').value,until:$('#ab-until').value,note:$('#ab-note').value.trim()};f.form=o;const er=m=>{$('#aberr').textContent=m};
  if(!okDate(o.from)||!okDate(o.until))return er(t('Date must be YYYY-MM-DD'));if(o.until<o.from)return er(t('The end date is before the start date.'));if(!ld&&o.uid!==u.id)return er(t('You can only record your own absence.'));
  if(o.kind!=='annual'&&!ld)return er(t('Sick and emergency leave are recorded by the lead.'));if(ABS.some(a=>a.uid===o.uid&&a.from<=o.until&&a.until>=o.from))return er(t('This person already has an absence in these dates.'));
  addAbs(Object.assign(o,{by:u.id}));audit('Absence recorded',U2[o.uid].name,`${ABK[o.kind]} ${o.from} → ${o.until}`+(o.note?' · '+o.note:''));f.form={uid:u.id,kind:'annual',from:TODAY,until:TODAY,note:''};toast(t('Absence recorded.'));render()},
