 abperson:el=>{const f=AF();f.person=el.dataset.a;f.sel=new Set();render()},abact:el=>{AF().act=el.dataset.a;render()},abscope:el=>{const f=AF();f.scope=el.dataset.a;if(f.scope==='site'&&!f.site)f.site=((openRowsOf(f.person)[0]||{}).s||{}).id||'';render()},
 absapply:()=>{const f=AF(),u=me(),rows=f.person?openRowsOf(f.person):[],sc=absScope(f,rows);if(!sc.length)return;if(!f.reason.trim()){f.err=t('A reason is required.');return render()}
  if(f.act==='reassign'&&!f.to){f.err=t('Nobody is eligible for all tasks in scope.');return render()}
  const bad=f.act==='behalf'?sc.filter(r=>!permOK(u,r.lv)):[];if(bad.length){f.err=t('You do not hold the permission level to act on {n} of these tasks.',{n:bad.length});return render()}
  const before=sc.map(r=>r.s.id+' '+STEPS[r.i].code+': '+holders(r.s,r.i,r.lv).map(h=>h.name).join('/')).join('; ');
  sc.forEach(r=>{const x=r.x,rs=f.reason.trim();if(f.act==='keep'){x.absKeep={by:u.id,at:TODAY,reason:rs};logH(x,'Kept with assignee',u.id,rs)}
   else{x.re=x.re||{};x.absKeep=null;x.re[r.lv]={to:f.act==='reassign'?f.to:u.id,from:f.person,by:u.id,at:TODAY,reason:rs,behalf:f.act==='behalf'?f.person:''};logH(x,f.act==='reassign'?'Reassigned':'Lead on behalf of the assignee',u.id,rs)}});
  const after=sc.map(r=>r.s.id+' '+STEPS[r.i].code+': '+holders(r.s,r.i,r.lv).map(h=>h.name).join('/')).join('; ');
  audit(f.act==='keep'?'Absence: kept with assignee':f.act==='reassign'?'Task reassigned':'Lead acted on behalf',U2[f.person].name,`${sc.length} task(s) · ${f.reason.trim()} · SLA not reset or paused`,before,after);
  f.reason='';f.err='';f.sel=new Set();toast(t('Decision applied to {n} task(s). SLA not reset or paused.',{n:sc.length}));render()},
